  put(Q.judge("ped-x-126", "ped-drill", "c13", "c13-k1", "课程体系改革中要处理共性与个性的关系，主要问题在于专业课的落实、教学质量的提高与管理的科学规范上。（ ）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-127", "ped-drill", "c7", "c7-k1", "在高校教师的主导作用主要是通过引导、点拨等方式来发挥。（ ）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-128", "ped-drill", "c7", "c7-k2", "在贯彻统一要求与因材施教相结合原则时，学生在认识、情感、性格、气质等方面的特点，是统一要求的基础。（ ）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-129", "ped-drill", "c10", "c10-k3", "学导式教学法从实践中看，它比较适合于语言方面的学习和成人高等教育的学习过程。（ ）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-130", "ped-drill", "c13", "c13-k2", "教学评价也被称作教学测量，是以教学目标为依据，运用可操作的科学手段，通过系统地收集有关教学的信息，对教学活动的过程和结果作出价值上的判断，并为被评价者的自我完善和有关部门的确科学决策提供依据的过程。（ ）", false, 1, "\n依据核验：测量赋予数量，评价还包含价值判断；两者不能作为同义词。 Seifert & Sutton，Educational Psychology 第12章：教师自编评价（公开教育心理学教材，非指定教材）；第12章 Basic concepts"), "《试卷合并卷》");
  put(Q.judge("ped-x-131", "ped-drill", "c13", "c13-k2", "终结性评价是与分等鉴定并作出关于对象的决策或资源的分配决策等相联系。（ ）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-132", "ped-drill", "c13", "c13-k2", "形成性评价的主要目的不是为了选拔少数优秀学生，而是为了发现每个学生的潜质，强化改进学生的学习，并为教师提供反馈。（ ）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-133", "ped-drill", "c13", "c13-k1", "对于一般的目标参照性测验，对区分度没有太高的要求。（ ）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-134", "ped-drill", "c0", "c0-k1", "高等教育终身化是指高等教育将不再是具有一定期限的人们接受教育的终结阶段。（ ）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-135", "ped-drill", "c7", "c7-k2", "柏拉图认为高等教育是培养具有理智和智慧的国家统治者。亚里士多德倡导发展学生理性的“博雅教育”。两位哲人的教育理念都表明了他们的教育价值观是个人本位的。（ ）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-136", "ped-drill", "c2", "c2-k1", "教育目的即教育方针，是指把受教育者培养成为一定社会需要的人的总要求。（ ）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-137", "ped-drill", "c7", "c7-k3", "在高校的师生工作关系中，学生的主动性明显增强。（ ）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-138", "ped-drill", "c9", "c9-k1", "从广义来说，课程是指学生在学校获得的全部经验。（ ）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-139", "ped-drill", "c9", "c9-k1", "布卢姆指出，，隐性课程不能很好地达到某些教学目标（特别是在品质、习惯、态度方面），因此与显性课程的明确目标相比无法长久保持。（ ）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-140", "ped-drill", "c1", "c1-k2", "高等教育的萌芽阶段，一般认为在西方为欧洲中世纪时代，在中国为唐宋时代。（ ）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-141", "ped-drill", "c1", "c1-k2", "1776年，美国颁布《独立宣言》后，开设了大量的赠地学院。（ ）（二）", false, 1, "\n依据核验：赠地大学制度对应1862年《莫里尔法案》，不能写成1776年独立宣言所产生的制度。 威斯康星大学Extension历史（大学原始校史资料）；1862年Morrill Act历史节点"), "《试卷合并卷》");
  put(Q.judge("ped-x-142", "ped-drill", "c2", "c2-k3", "教育方针由中央或党的最高领导人制定，每一个时期表述不同，因此无法写进法律之中。 （ ） （三）", false, 1, "\n依据核验：教育方针可以并已经通过法律体现，不能称无法写进法律。 中华人民共和国教育法（2021修正）（法律）；教育法第五条"), "《试卷合并卷》");
  put(Q.judge("ped-x-143", "ped-drill", "c7", "c7-k2", "高等学校的主体是教师、学生、学校建筑。（ ） （五）", false, 1, "\n依据核验：学校建筑为物，不能与教师、学生并列为享有权利承担义务的主体。 中华人民共和国民法典（法律）；中华人民共和国高等教育法（2018修正）（法律）；民法典主体制度；高等教育法第三十条"), "《试卷合并卷》");
  put(Q.judge("ped-x-144", "ped-drill", "c9", "c9-k3", "教材是高校学科建设的核心内容，直接决定教学的成败。（ ） （六）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-145", "ped-drill", "c9", "c9-k1", "布鲁纳认为，隐性课程与显性课程同样重要。 （ ） （六）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-146", "ped-drill", "c8", "c8-k3", "班级授课制萌芽于15世纪末，后经德国教育家赫尔巴特总结、改进和理论提升，初步形成。 （ ）", false, 1, "\n依据核验：班级授课理论在夸美纽斯时期已获系统阐述，不能说由后来赫尔巴特最初创立或初步理论化。 西安科技大学教师发展中心：大小班教学模式效果研究（高校发布的教学研究资料，非指定教材）；导论：17世纪夸美纽斯《大教学论》"), "《试卷合并卷》");
  put(Q.judge("ped-x-147", "ped-drill", "c10", "c10-k2", "100人以上的大班教学，不适宜于用课堂讨论法进行教学。 （ ）（八）", false, 1, "\n依据核验：大班可采用两人或小组讨论等组织方式，人数超过100并不排除讨论法。 康奈尔大学：在课堂中组织讨论（大学教学中心原始指导）；中大班讨论建议"), "《试卷合并卷》");
  put(Q.judge("ped-x-148", "ped-drill", "c14", "c14-k1", "大学与中学有着本质的不同，因此中学的教学改革方法和模式不适合天大学借鉴。（ ）（ 八）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-149", "ped-drill", "c13", "c13-k1", "效度指的是考试结果的稳定性和可靠性程度，即考试结果是否真实、客观地反映了学生的实际水平。 （ ） （八）", false, 1, "\n依据核验：稳定性、一致性属于信度；效度关注是否测到预定测量对象，原题混淆二者。 OpenStax Psychology 2e §2.3：相关、信度与效度（公开教材，非指定教材）；§2.3 Reliability and Validity"), "《试卷合并卷》");
