  put(Q.judge("ped-x-180", "ped-drill", "c13", "c13-k1", "《国家中长期教育改革和发展规划纲要(2010-2020年)》规定国家财政性教育经费支出占国内生产总值比例于2012年必须达到4％。（ ）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-181", "ped-drill", "c8", "c8-k1", "教学型高校的教师不需要开展任何科研活动。", false, 1, "按核验意见修订：教学型高校同样承担科研与教学研究任务，教师应结合岗位参与。"), "《试卷合并卷》（v1.31 修订）");
  put(Q.judge("ped-x-182", "ped-drill", "c13", "c13-k1", "教育改革发展的核心任务是提高质量。（ ）", true, 1, ""), "《试卷合并卷》");
