  put(Q.judge("ped-x-266", "ped-drill", "c3", "c3-k2", "专门人才是指具有某一方面人才的人，不包括通才。（ ）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-267", "ped-drill", "c14", "c14-k1", "世界高等教育的管理模式主要有集权式和分权式。（ ）", true, 1, ""), "《试卷合并卷》");
