  put(Q.judge("ped-x-269", "ped-drill", "c8", "c8-k1", "高等学校的教学过程是教学生掌握知识的过程。（ ）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-270", "ped-drill", "c8", "c8-k3", "备课就是编写教案。（ ）", false, 1, "\n依据核验：备课还包含目标、学习者、活动及评价的规划，不能缩为写教案或仅钻研教材。 Seifert & Sutton，Educational Psychology 第11章：教学规划（公开教育心理学教材，非指定教材）；第11章：目标、资源、教学活动与评价规划"), "《试卷合并卷》");
  put(Q.judge("ped-x-271", "ped-drill", "c6", "c6-k3", "一个大学科研能力和水平的高低是衡量其层次和地位的唯一标志。（ ）", true, 1, ""), "《试卷合并卷》");
