  put(Q.judge("ped-x-273", "ped-drill", "c5", "c5-k1", "高校具有办学自主权和法人资格。（ ）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-274", "ped-drill", "c3", "c3-k1", "实施宽口径，适应性强的教育是通才教育。（ ）", true, 1, ""), "《试卷合并卷》");
