  put(Q.judge("ped-x-282", "ped-drill", "c0", "c0-k1", "我国颁布的第一部有关高等教育的法律是《中华人民共和国高等教育法》。（ ）", false, 1, "\n依据核验：1980年已有涉及高等教育学位制度的教育法律，不能把1998年高等教育法说成首部一切有关高教的法律。 教育部：1980年学位条例草案全票通过（教育部立法历史资料）；1980年学位条例；1998年高等教育法"), "《试卷合并卷》");
  put(Q.judge("ped-x-283", "ped-drill", "c1", "c1-k1", "西方历史上公认的教育家有苏格拉底、柏拉图、亚里士多德、伊壁鸠鲁、芝诺以及“智者派”成员，而在中国，春秋战国时期的诸子百家，都在中国高等教育发展史上影响深刻，尤其是伟大的教与学孔子和孟子，已成为世界上公认的早期高等教育思想家。（ ）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-284", "ped-drill", "c1", "c1-k2", "威斯康星大学校长范·海斯提出大学应忠实地为社会需要服务，这一思想强化了大学的社会服务职能。", true, 1, "按核验意见修订：“威斯康星思想”强调大学为社会服务，强化了社会服务职能。"), "《试卷合并卷》（v1.31 修订）");
  put(Q.judge("ped-x-286", "ped-drill", "c7", "c7-k2", "高等学校实施全面发展教育的最基本途径是发展学生的素质（ ）。", true, 1, ""), "《试卷合并卷》");
