  put(Q.judge("ped-x-291", "ped-drill", "c9", "c9-k1", "大、中、小课程是根据上课人数来分类的（ ）。", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-292", "ped-drill", "c13", "c13-k2", "按教学评价的不同目的、作用及时间来分，教学评价主要分为诊断性评价、形成性评价和终结性评价三种，其中诊断性评价是为了发现每个学生的潜质，强化改进学生的学习，并为教师提供反馈。（ ）", false, 1, "\n依据核验：原题把教学过程中反馈改进的形成性功能直接等同诊断性评价，应区分评价目的与时点。 Seifert & Sutton，Educational Psychology 第12章：教师自编评价（公开教育心理学教材，非指定教材）；Seifert & Sutton，Educational Psychology 第13章：正式测评（公开教育心理学教材，非指定教材）；形成性评价；Diagnostic tests"), "《试卷合并卷》");
  put(Q.judge("ped-x-293", "ped-drill", "c10", "c10-k2", "课堂讨论法是我国高等学校教学最普遍采用的方法。（ ）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-295", "ped-drill", "c7", "c7-k1", "教育史学家认为，人类教育史上曾经历过三次重大革命，第一次革命是出现了专职教师，第二次革命是出现了文字，第三次革命是印刷术的发明与应用。（ ）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-297", "ped-drill", "c10", "c10-k3", "现场教学法是在社会实践中进行教学活动的组织形式，包括参观法和调查法。（ ）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-298", "ped-drill", "c5", "c5-k1", "依法治教是教育行政管理的范围扩大和职能转变的必然要求。（ ）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-299", "ped-drill", "c9", "c9-k1", "西方最早提出课程概念的是斯宾塞。（ ）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-300", "ped-drill", "c9", "c9-k1", "公共课程可以分为公共必修课程和专业必修课程，公共必修课程包括公共课程、基础课程，专业必修课程包括专业基础课程等。（ ）", true, 1, ""), "《试卷合并卷》");
