  put(Q.judge("ped-x-304", "ped-drill", "c13", "c13-k1", "高校扩招是导致教学质量下降和毕业生就业困难的唯一原因。", false, 1, "按核验意见修订：质量与就业受多重因素影响，不能把扩招认定为唯一原因。"), "《试卷合并卷》（v1.31 修订）");
  put(Q.judge("ped-x-305", "ped-drill", "c1", "c1-k2", "1776年，美国颁布《独立宣言》后，开设了大量的赠地学院。（ ）", false, 1, "\n依据核验：赠地大学制度对应1862年《莫里尔法案》，不能写成1776年独立宣言所产生的制度。 威斯康星大学Extension历史（大学原始校史资料）；1862年Morrill Act历史节点"), "《试卷合并卷》");
  put(Q.judge("ped-x-306", "ped-drill", "c7", "c7-k2", "高等学校的主体是教师、学生、学校建筑。（ ）", false, 1, "\n依据核验：学校建筑为物，不能与教师、学生并列为享有权利承担义务的主体。 中华人民共和国民法典（法律）；中华人民共和国高等教育法（2018修正）（法律）；民法典主体制度；高等教育法第三十条"), "《试卷合并卷》");
  put(Q.judge("ped-x-307", "ped-drill", "c9", "c9-k3", "教材是高校学科建设的核心内容，直接决定教学的成败。（ ）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-308", "ped-drill", "c9", "c9-k1", "布鲁纳认为，隐性课程与显性课程同样重要。 （ ）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-309", "ped-drill", "c8", "c8-k3", "班级授课制萌芽于15世纪末，后经德国教育家赫尔巴特总结、改进和理论提升，初步形成。 （ ）", false, 1, "\n依据核验：班级授课理论在夸美纽斯时期已获系统阐述，不能说由后来赫尔巴特最初创立或初步理论化。 西安科技大学教师发展中心：大小班教学模式效果研究（高校发布的教学研究资料，非指定教材）；导论：17世纪夸美纽斯《大教学论》"), "《试卷合并卷》");
  put(Q.judge("ped-x-310", "ped-drill", "c10", "c10-k2", "100人以上的大班教学，不适宜于用课堂讨论法进行教学。 （ ）", false, 1, "\n依据核验：大班可采用两人或小组讨论等组织方式，人数超过100并不排除讨论法。 康奈尔大学：在课堂中组织讨论（大学教学中心原始指导）；中大班讨论建议"), "《试卷合并卷》");
  put(Q.judge("ped-x-311", "ped-drill", "c14", "c14-k1", "大学与中学有着本质的不同，因此中学的教学改革方法和模式不适合大学借鉴。（ ）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-312", "ped-drill", "c13", "c13-k1", "效度指的是考试结果的稳定性和可靠性程度，即考试结果是否真实、客观地反映了学生的实际水平。 （ ）", false, 1, "\n依据核验：稳定性、一致性属于信度；效度关注是否测到预定测量对象，原题混淆二者。 OpenStax Psychology 2e §2.3：相关、信度与效度（公开教材，非指定教材）；§2.3 Reliability and Validity"), "《试卷合并卷》");
  put(Q.judge("ped-x-313", "ped-drill", "c7", "c7-k2", "本科大学生未经过系统的学术训练，不用要求他们写毕业论文。 （ ）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-315", "ped-drill", "c4", "c4-k2", "我国学位的级别分为学士、硕士、博士和博士后四级。（ ）", false, 1, "\n依据核验：学历与学位不同；学位为学士、硕士、博士，博士后不是学位层级。 中华人民共和国学位法（2025年1月1日起施行）（法律）；中华人民共和国高等教育法（2018修正）（法律）；学位法第二条；高等教育法第二十、二十二条"), "《试卷合并卷》");
  put(Q.judge("ped-x-316", "ped-drill", "c4", "c4-k3", "专业的设置与调整是以一定社会分工为前提的。（ ）（P112） （划分）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-317", "ped-drill", "c8", "c8-k1", "教学过程是学生在老师指导下的一种特殊的认识过程。（ ）", true, 1, ""), "《试卷合并卷》");
  put(Q.judge("ped-x-318", "ped-drill", "c8", "c8-k1", "教学原则是依托已发现的教学规律和一定教育目的，对教师和教学工作者提出的在教学过程中必须遵守的基本原则。（ ）（P121） （要求）", true, 1, ""), "《试卷合并卷》");
