  put(Q.judge("ped-sup-049", "ped-main", "c14", "c14-k1", "人才培养模式改革是高等教育模式创新的重要内容。", true, 1, "人才培养模式是教育模式的核心组成部分。"), "教材目录自编");
  put(Q.blank("ped-sup-050", "ped-drill", "c14", "c14-k1", "以学生发展为中心、注重能力培养的人才培养模式通常称为____导向模式。", ["能力", "成果"], 2, "能力导向/成果导向（OBE）强调以学生学习成果为中心。"), "教材目录自编");
  put(Q.multiple("ped-sup-051", "ped-main", "c5", "c5-k3", "中国特色现代大学制度建设的路径包括（　　）", ["依法治校", "教授治学", "管办评分离", "行政化"], ["A", "B", "C"], 3, "依法治校、教授治学、管办评分离是建设中国特色现代大学制度的重要路径。"), "教材目录自编");
