  put(Q.judge("ped-sup-054", "ped-drill", "c13", "c13-k3", "专业认证是高等教育质量评价的重要方式。", true, 1, "专业认证与审核评估都是高等教育质量评价的重要形式。"), "教材目录自编");
  put(Q.judge("ped-sup2-001", "ped-main", "c3", "c3-k1", "设计高等教育目标系统只需考虑社会需要，不必考虑学生发展。", false, 1, "目标设计要兼顾社会需要与学生发展。\n依据核验：人才培养须兼顾社会需要和学习者发展，不可排除学生发展。 中华人民共和国高等教育法（2018修正）（法律）；Seifert & Sutton，Educational Psychology 第11章：教学规划（公开教育心理学教材，非指定教材）；高等教育法第五条；教学目标规划"), "原题库");
  put(Q.blank("ped-sup2-002", "ped-main", "c3", "c3-k3", "高等教育目标系统一般包括高等教育目的、高等学校培养目标和____培养目标。", ["专业"], 2, "三个层次为高等教育目的、学校培养目标、专业培养目标。"), "原题库");
