  put(Q.single("ped-sup2-026", "ped-main", "c10", "c10-k1", "教学方法的核心是（　　）", ["教师教与学生学的方式", "教学设备", "教材", "课程表"], "A", 2, "教学方法指教与学相互作用的方式。"), "原题库");
