  put(Q.single("ped-sup2-029", "ped-main", "c10", "c10-k2", "以真实案例组织学生讨论分析的方法是（　　）", ["案例教学法", "讲授法", "演示法", "读书指导法"], "A", 2, "案例教学以真实案例为载体。"), "原题库");
